{
  "headline": "Cadence has strong unit economics fundamentals — 75% gross margin and a 2.14x burn multiple — but the model is a thin slice of actuals with no projections, missing CAC, and only ~12.5 months of runway, which will be the first thing investors flag.",
  "investor_talking_points": [
    "We're at $702K ARR growing 8% month-over-month with 75% gross margins — the economics are solid at the unit level.",
    "Our burn multiple is 2.14x, which is in the acceptable range for a seed-stage sales-led SaaS company.",
    "We have $1.5M in cash supporting a $120K monthly burn — we're actively fundraising to extend runway to 24+ months and fund the next phase of growth."
  ],
  "lenses": {
    "runway": {
      "callout": "~12.5 months of runway at current $120K/month burn — meaningfully below the 18-month seed-stage comfort floor.",
      "highlight": "Slow-growth scenario (13 months) and crisis scenario (10 months) both show cash-out before late 2027, reinforcing urgency to close a round.",
      "watch_out": "Burn is already more than 2x current MRR ($58.5K). Without revenue acceleration or expense discipline, runway compresses further as headcount likely grows."
    },
    "unit_economics": {
      "callout": "75% gross margin is strong for B2B SaaS; burn multiple of 2.14x is acceptable but not exceptional — investors will want to see it improve as revenue scales.",
      "watch_out": "CAC is entirely absent from the model. For a sales-led SaaS, the inability to show LTV/CAC ratio or payback period is a critical gap that investors will block on."
    }
  }
}

